package id.putusan.dashboard.ui;

import id.putusan.dashboard.model.Putusan;import id.putusan.dashboard.repository.PutusanRepository;import id.putusan.dashboard.service.StatistikService;
import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.LinkedHashMap;import java.util.Map;

public class StatistikPanel extends JPanel {
 public StatistikPanel(PutusanRepository repo){setLayout(new BorderLayout(0,16));setBackground(UiStyle.BG);setBorder(new EmptyBorder(24,28,24,28));JLabel title=new JLabel("Statistik Perkara");title.setFont(new Font("SansSerif",Font.BOLD,25));JLabel sub=UiStyle.muted("Ringkasan agregat dari data putusan yang tersedia.");JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.add(title);h.add(Box.createVerticalStrut(5));h.add(sub);add(h,BorderLayout.NORTH);
  JPanel body=new JPanel(new GridLayout(1,2,14,14));body.setOpaque(false);JPanel summary=UiStyle.card();summary.setLayout(new BorderLayout(0,12));JLabel st=new JLabel("Ikhtisar statistik");st.setFont(new Font("SansSerif",Font.BOLD,15));JTextArea text=new JTextArea(new StatistikService().summary(repo.all()));text.setEditable(false);text.setOpaque(false);text.setFont(new Font("SansSerif",Font.PLAIN,15));text.setForeground(UiStyle.TEXT);text.setBorder(new EmptyBorder(10,0,0,0));summary.add(st,BorderLayout.NORTH);summary.add(text,BorderLayout.CENTER);
  Map<String,Integer> types=new LinkedHashMap<>();for(int i=0;i<repo.all().size();i++){String t=repo.all().get(i).getJenisNarkotika();if(t!=null&&!t.isBlank())types.put(t,types.getOrDefault(t,0)+1);}JPanel chart=UiStyle.card();chart.setLayout(new BorderLayout(0,12));JLabel ct=new JLabel("Sebaran jenis narkotika");ct.setFont(new Font("SansSerif",Font.BOLD,15));chart.add(ct,BorderLayout.NORTH);JPanel bars=new JPanel();bars.setOpaque(false);bars.setLayout(new BoxLayout(bars,BoxLayout.Y_AXIS));int max=1;for(int v:types.values())max=Math.max(max,v);for(Map.Entry<String,Integer> e:types.entrySet()){JPanel row=new JPanel(new BorderLayout(8,5));row.setOpaque(false);JLabel name=new JLabel(e.getKey());name.setFont(new Font("SansSerif",Font.PLAIN,12));JLabel count=new JLabel(String.valueOf(e.getValue()));count.setForeground(UiStyle.MUTED);JProgressBar bar=new JProgressBar(0,max);bar.setValue(e.getValue());bar.setStringPainted(false);bar.setForeground(UiStyle.TEAL);bar.setBackground(new Color(235,240,245));bar.setBorderPainted(false);JPanel labels=new JPanel(new BorderLayout());labels.setOpaque(false);labels.add(name,BorderLayout.WEST);labels.add(count,BorderLayout.EAST);row.add(labels,BorderLayout.NORTH);row.add(bar,BorderLayout.SOUTH);bars.add(row);bars.add(Box.createVerticalStrut(14));}if(types.isEmpty())bars.add(UiStyle.muted("Tidak ada data kategori."));chart.add(bars,BorderLayout.CENTER);body.add(summary);body.add(chart);add(body,BorderLayout.CENTER);
 }
}
